// ============================================================================
//  EMAIL DIARIO "HOY" (workflow 06, 15-sep-2026)
//  Lo que la recepcion necesita ver al abrir la clinica, en un solo correo:
//    1. Pacientes a los que hay que llamar (derivaciones pendientes), arriba y
//       en rojo, con telefono y boton "Marcar como atendida".
//    2. Las citas de hoy, en orden.
//    3. La lista de espera pendiente.
//    4. Los interesados (leads) de las ultimas 24 horas.
//  Multi-clinica: una consulta por tabla y un email por clinica activa.
//  Minimizacion de datos: aqui NO va lo que conto el paciente sobre su salud;
//  eso solo viaja en el email de la propia derivacion.
// ============================================================================
const soloFilas = arr => arr.map(i => i.json || {}).filter(r => r && r.id);
const clinicas     = soloFilas($('Cargar clinicas').all());
const citas        = soloFilas($('Cargar citas').all());
const derivaciones = soloFilas($('Cargar derivaciones pendientes').all());
const espera       = soloFilas($('Cargar lista de espera').all());
const leads        = soloFilas($('Cargar leads').all());

if (!clinicas.length) return [];

// Direccion de tu n8n para el boton "Marcar como atendida" (workflow 07).
// Se saca de la propia ejecucion. Si algun dia el enlace sale mal, escribela a
// mano, por ejemplo 'https://tuinstancia.app.n8n.cloud'.
const URL_N8N_MANUAL = '';
const baseN8n = (URL_N8N_MANUAL || ($execution.resumeUrl || '').replace(/\/webhook-waiting\/.*$/, '')).replace(/\/+$/, '');
const enlaceCierre = d => (baseN8n && d.derivacion_id && d.token_cierre)
  ? baseN8n + '/webhook/derivacion-atendida?id=' + encodeURIComponent(d.derivacion_id) + '&t=' + encodeURIComponent(d.token_cierre)
  : '';

const esc = v => (v === null || v === undefined ? '' : v.toString())
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;').replace(/'/g, '&#39;');

const diaISO = (fecha, tz) => {
  const p = new Intl.DateTimeFormat('en-CA', { timeZone: tz, year: 'numeric', month: '2-digit', day: '2-digit' }).formatToParts(fecha);
  const g = t => p.find(x => x.type === t).value;
  return g('year') + '-' + g('month') + '-' + g('day');
};
const normFecha = f => {
  const m = (f || '').toString().trim().match(/^(\d{4})-(\d{2})-(\d{2})/);
  return m ? m[1] + '-' + m[2] + '-' + m[3] : '';
};
const normHora = h => {
  const m = (h || '').toString().trim().match(/^(\d{1,2}):(\d{2})/);
  return m ? m[1].padStart(2, '0') + ':' + m[2] : (h || '').toString();
};
const aES = iso => (iso || '').split('-').reverse().join('/');
const diaLargo = iso => new Intl.DateTimeFormat('es-ES', { timeZone: 'UTC', weekday: 'long', day: 'numeric', month: 'long' })
  .format(new Date(iso + 'T12:00:00Z'));
const telVisible = t => {
  const d = (t || '').toString().replace(/\D/g, '');
  return d ? '+' + d : '';
};
const antiguedad = iso => {
  const ms = Date.parse(iso);
  if (!Number.isFinite(ms)) return '';
  const horas = Math.floor((Date.now() - ms) / 3600000);
  if (horas < 1) return 'hace menos de 1 h';
  if (horas < 48) return 'hace ' + horas + ' h';
  return 'hace ' + Math.floor(horas / 24) + ' días';
};

const td = 'padding:8px;border-bottom:1px solid #eee;vertical-align:top';
const tabla = (cabeceras, filas) => '<table style="width:100%;border-collapse:collapse;margin:6px 0 20px;font-size:14px">'
  + '<tr>' + cabeceras.map(c => '<th style="text-align:left;padding:8px;border-bottom:2px solid #ddd;color:#555">' + esc(c) + '</th>').join('') + '</tr>'
  + filas.join('') + '</table>';
const vacio = texto => '<p style="color:#888;margin:6px 0 20px">' + esc(texto) + '</p>';
const celda = (contenido, extra) => '<td style="' + td + (extra ? ';' + extra : '') + '">' + contenido + '</td>';

return clinicas.map(clinica => {
  const tz = clinica.zona_horaria || 'Europe/Madrid';
  const hoy = diaISO(new Date(), tz);
  const mias = arr => arr.filter(r => r.clinica_id === clinica.id);

  const derivC = mias(derivaciones)
    .sort((a, b) => (Date.parse(a.creado_en) || 0) - (Date.parse(b.creado_en) || 0));
  const citasHoy = mias(citas)
    .filter(c => (c.estado || '') === 'confirmada' && normFecha(c.fecha) === hoy)
    .sort((a, b) => normHora(a.hora).localeCompare(normHora(b.hora)));
  const esperaC = mias(espera)
    .filter(e => (e.estado || '') === 'pendiente' && normFecha(e.fecha) >= hoy)
    .sort((a, b) => (normFecha(a.fecha) + normHora(a.hora)).localeCompare(normFecha(b.fecha) + normHora(b.hora)));
  const leadsC = mias(leads);

  const bloqueDerivaciones = derivC.length
    ? '<h3 style="color:#d9534f;margin:18px 0 2px">⚠️ Pacientes a los que hay que llamar (' + derivC.length + ')</h3>'
      + '<p style="color:#666;margin:2px 0 6px;font-size:13px">Mientras estén pendientes, el asistente no les contesta consultas. Cuando habléis con el paciente, pulsad "Marcar como atendida".</p>'
      + tabla(['Paciente', 'Teléfono', 'Motivo', 'Desde', ''], derivC.map(d => {
        const enlace = enlaceCierre(d);
        return '<tr>'
          + celda('<b>' + esc(d.nombre || 'Sin nombre') + '</b>')
          + celda('<a href="tel:' + esc(telVisible(d.telefono)) + '">' + esc(telVisible(d.telefono)) + '</a>')
          + celda(esc(d.motivo || ''))
          + celda(esc(antiguedad(d.creado_en)), 'color:#888')
          + celda(enlace ? '<a href="' + esc(enlace) + '" style="color:#1a7f5a;font-weight:bold">Marcar como atendida</a>' : '')
          + '</tr>';
      }))
    : '';

  const bloqueCitas = '<h3 style="color:#1a7f5a;margin:18px 0 2px">Citas de hoy (' + citasHoy.length + ')</h3>'
    + (citasHoy.length
      ? tabla(['Hora', 'Paciente', 'Tratamiento', 'Teléfono'], citasHoy.map(c => '<tr>'
        + celda('<b>' + esc(normHora(c.hora)) + '</b>')
        + celda(esc(c.nombre || ''))
        + celda(esc(c.tratamiento || ''))
        + celda(esc(telVisible(c.telefono)))
        + '</tr>'))
      : vacio('Hoy no hay citas reservadas por WhatsApp.'));

  const bloqueEspera = '<h3 style="color:#8a4b16;margin:18px 0 2px">Lista de espera (' + esperaC.length + ')</h3>'
    + (esperaC.length
      ? tabla(['Quiere', 'Paciente', 'Tratamiento', 'Teléfono'], esperaC.slice(0, 20).map(e => '<tr>'
        + celda(esc(aES(normFecha(e.fecha)) + ' ' + normHora(e.hora)))
        + celda(esc(e.nombre || ''))
        + celda(esc(e.tratamiento || ''))
        + celda(esc(telVisible(e.telefono)))
        + '</tr>'))
      : vacio('Nadie esperando hueco.'));

  const bloqueLeads = '<h3 style="color:#8a4b16;margin:18px 0 2px">Interesados de las últimas 24 h (' + leadsC.length + ')</h3>'
    + (leadsC.length
      ? tabla(['Persona', 'Le interesa', 'Teléfono'], leadsC.slice(0, 20).map(l => '<tr>'
        + celda(esc(l.nombre || 'Sin nombre'))
        + celda(esc(l.tratamiento_interes || ''))
        + celda(esc(telVisible(l.telefono)))
        + '</tr>'))
      : vacio('Ningún interesado nuevo.'));

  const html = [
    '<div style="font-family:Arial,Helvetica,sans-serif;max-width:680px;color:#222">',
    '<h2 style="color:#1a7f5a;border-bottom:3px solid #1a7f5a;padding-bottom:10px;margin-bottom:4px">Hoy en ' + esc(clinica.nombre) + '</h2>',
    '<p style="color:#666;margin-top:0">' + esc(diaLargo(hoy)) + '</p>',
    bloqueDerivaciones,
    bloqueCitas,
    bloqueEspera,
    bloqueLeads,
    '<p style="color:#999;font-size:12px;margin-top:24px;border-top:1px solid #eee;padding-top:12px">',
    'Resumen automático del asistente de WhatsApp. Solo incluye lo que ha pasado por el asistente: las citas que apuntáis a mano en la agenda no aparecen aquí.',
    '</p>',
    '</div>'
  ].join('');

  const asunto = 'Hoy en ' + clinica.nombre + ': ' + citasHoy.length + (citasHoy.length === 1 ? ' cita' : ' citas')
    + (derivC.length ? ' y ' + derivC.length + (derivC.length === 1 ? ' paciente' : ' pacientes') + ' por llamar' : '');

  return {
    json: {
      clinica_id: clinica.id,
      email_avisos: clinica.email_avisos,
      email_subject: asunto,
      email_html: html
    }
  };
}).filter(item => !!item.json.email_avisos);
